def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); best=[]
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r,c) in seen: continue
            color=grid[r][c]; comp=[(r,c)]; seen.add((r,c))
            for y,x in comp:
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); comp.append((yy,xx))
            if len(comp)>len(best): best=comp
    if not best: return [row[:] for row in grid]
    y0=min(y for y,x in best); y1=max(y for y,x in best)
    x0=min(x for y,x in best); x1=max(x for y,x in best)
    out=[[0]*(x1-x0+1) for _ in range(y1-y0+1)]
    for y,x in best: out[y-y0][x-x0]=grid[y][x]
    return out

